let resultsData = $('Markdown - results').first()?.json?.data_results || "";
let evalData = $('Markdown - eval').first()?.json?.data_eval || "";

const tableStyle = 'style="border: 1px solid #333; border-collapse: collapse; width: 100%;"';
const cellStyle = 'style="border: 1px solid #333; padding: 10px;"';

resultsData = resultsData.replace(/<table/g, `<table ${tableStyle}`).replace(/<td/g, `<td ${cellStyle}`).replace(/<th/g, `<th ${cellStyle}`);
evalData = evalData.replace(/<table/g, `<table ${tableStyle}`).replace(/<td/g, `<td ${cellStyle}`).replace(/<th/g, `<th ${cellStyle}`);

const form = $('On form submission').first()?.json;
return {
  email: form?.Email || "candidate@example.com",
  subject: `Dish evaluation report - ${form?.['Recipe name'] || 'Recipe'}`, 
  html_body: `<div class="results-section">${resultsData}</div><div style="margin: 20px 0; font-weight: bold; border-top: 1px solid #eee;">--- MODEL EVALUATION ---</div><div class="evaluation-section">${evalData}</div>`
};
